22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws OwnerIdentityDuplicateException {
25	        String key = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(),
26	                owner.getHouseholdId());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
29	                continue; // never compare the new owner against itself
30	            }
31	            String other = OwnerIdentity.identityKey(existing.getTelephone(), existing.getEmail(),
32	                    existing.getHouseholdId());
33	            if (key.equals(other)) {
34	                throw new OwnerIdentityDuplicateException(key);
35	            }
36	        }
37	    }
